1	/**
2	 * Supabase-generated-style database types for CROBOT.
3	 *
4	 * These types mirror the SQL schema in supabase/migrations/ and are fully
5	 * compatible with the app-level types in src/types/index.ts.
6	 *
7	 * Usage:
8	 *   import { createClient } from '@supabase/supabase-js'
9	 *   import type { Database } from '@/types/database'
10	 *
11	 *   const supabase = createClient<Database>(url, key)
12	 *   const { data } = await supabase.from('scans').select('*')
13	 *   // data is typed as Tables<'scans'>[]
14	 */
15	
16	import type { CroPillar, CopyRewriteElementType, PageType, PlanType, ScanStatus, Severity, Effort, UserRole, CompetitorGroup, CompetitorUrl, TeamMemberRole, ApiKey, WebhookEndpoint } from "./index";
17	
18	export type { ScanHistoryEntry as ScanHistoryRow } from "./index";
19	
20	// ── Finding (JSONB shape stored inside scan_results.findings) ─
21	// Must stay in sync with the Finding interface in index.ts.
22	
23	export interface DbFinding {
24	  id: string;
25	  title: string;
26	  severity: Severity;
27	  current_state: string;
28	  recommendation: string;
29	  ai_suggestion: string;
30	  is_premium: boolean;
31	  effort: Effort;
32	  estimated_lift: string;
33	  category: string;
34	}
35	
