43	function getPlanFromProductId(productId: string): PlanType {
44	  const starterMonthly = Deno.env.get("DODO_PRODUCT_STARTER_MONTHLY");
45	  const starterAnnual = Deno.env.get("DODO_PRODUCT_STARTER_ANNUAL");
46	  const growthMonthly = Deno.env.get("DODO_PRODUCT_GROWTH_MONTHLY");
