50	  const agencyMonthly = Deno.env.get("DODO_PRODUCT_AGENCY_MONTHLY");
51	  const agencyAnnual = Deno.env.get("DODO_PRODUCT_AGENCY_ANNUAL");
52	
53	  if (productId === starterMonthly || productId === starterAnnual) return "starter";
54	  if (productId === growthMonthly || productId === growthAnnual) return "growth";
55	  if (productId === proMonthly || productId === proAnnual) return "pro";
