/**
 * webhook-dispatch — Edge Function (Internal)
 *
 * Dispatches scan.completed events to all active webhook endpoints
 * registered by a user.
 *
 * Called internally from analyze-url (fire-and-forget, not user-facing).
 * Auth: Bearer service_role key only.
 *
 * Required env vars:
 *   SUPABASE_URL
 *   SUPABASE_SERVICE_ROLE_KEY
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── Types ─────────────────────────────────────────────────────

interface WebhookDispatchBody {
  user_id: string;
  event: string;
  payload: ScanCompletedPayload;
}

interface ScanCompletedPayload {
  scan_id: string;
  url: string;
  overall_score: number;
  issues_found: number;
  critical_issues: number;
  completed_at: string;
}

interface WebhookEndpointRow {
  id: string;
  url: string;
  events: string[];
  secret: string;
  is_active: boolean;
}

// ── HMAC signing ──────────────────────────────────────────────

async function signPayload(secret: string, payload: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const sig = await crypto.subtle.sign(
    "HMAC",
    key,
    new TextEncoder().encode(payload),
  );
  return Array.from(new Uint8Array(sig))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

// ── Dispatch to a single endpoint ────────────────────────────

async function dispatchToEndpoint(
  endpoint: WebhookEndpointRow,
  event: string,
  payloadJson: string,
): Promise<void> {
  const signature = await signPayload(endpoint.secret, payloadJson);

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 10_000);

  try {
    const res = await fetch(endpoint.url, {
      method: "POST",
      signal: controller.signal,
      headers: {
        "Content-Type": "application/json",
        "X-ConvertScan-Signature": `sha256=${signature}`,
        "X-ConvertScan-Event": event,
      },
      body: payloadJson,
    });

    if (!res.ok) {
      console.warn(
        `Webhook delivery failed for endpoint ${endpoint.id}: HTTP ${res.status}`,
      );
    } else {
      console.log(`Webhook delivered to endpoint ${endpoint.id}: HTTP ${res.status}`);
    }
  } catch (err) {
    if (err instanceof Error && err.name === "AbortError") {
      console.warn(`Webhook timed out for endpoint ${endpoint.id}`);
    } else {
      console.warn(`Webhook error for endpoint ${endpoint.id}:`, err);
    }
  } finally {
    clearTimeout(timeoutId);
  }
}

// ── Handler ───────────────────────────────────────────────────

serve(async (req: Request) => {
  // Internal-only — reject non-POST
  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { "Content-Type": "application/json" },
    });
  }

  // Verify service_role auth
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.replace(/^Bearer\s+/i, "");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

  if (!token || token !== serviceRoleKey) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { "Content-Type": "application/json" },
    });
  }

  let body: WebhookDispatchBody;
  try {
    body = (await req.json()) as WebhookDispatchBody;
  } catch {
    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
      status: 400,
      headers: { "Content-Type": "application/json" },
    });
  }

  const { user_id, event, payload } = body;

  if (!user_id || !event || !payload) {
    return new Response(
      JSON.stringify({ error: "Missing required fields: user_id, event, payload" }),
      { status: 400, headers: { "Content-Type": "application/json" } },
    );
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  if (!supabaseUrl) {
    return new Response(JSON.stringify({ error: "SUPABASE_URL not set" }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }

  const supabase = createClient(supabaseUrl, serviceRoleKey);

  // Fetch all active endpoints subscribed to this event
  const { data: endpoints, error: fetchError } = await supabase
    .from("webhook_endpoints")
    .select("id, url, events, secret, is_active")
    .eq("user_id", user_id)
    .eq("is_active", true);

  if (fetchError) {
    console.error("Failed to fetch webhook endpoints:", fetchError.message);
    return new Response(
      JSON.stringify({ error: "Failed to fetch endpoints" }),
      { status: 500, headers: { "Content-Type": "application/json" } },
    );
  }

  const matching = (endpoints as WebhookEndpointRow[]).filter(
    (ep) => Array.isArray(ep.events) && ep.events.includes(event),
  );

  if (matching.length === 0) {
    return new Response(
      JSON.stringify({ dispatched: 0 }),
      { status: 200, headers: { "Content-Type": "application/json" } },
    );
  }

  const payloadJson = JSON.stringify(payload);

  // Fire all dispatches in parallel (non-fatal per endpoint)
  await Promise.allSettled(
    matching.map((ep) => dispatchToEndpoint(ep, event, payloadJson)),
  );

  return new Response(
    JSON.stringify({ dispatched: matching.length }),
    { status: 200, headers: { "Content-Type": "application/json" } },
  );
});

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { WebhookEndpoint } from "@/types/index";
import type { WebhookEndpointInsert } from "@/types/database";

// ── Query keys ─────────────────────────────────────────────────

export const webhookKeys = {
  all: ["webhook_endpoints"] as const,
};

// ── useWebhooks ────────────────────────────────────────────────
// Fetches all webhook endpoints for the current user.

export function useWebhooks() {
  const { profile } = useAuth();
  const userId = profile?.id;

  return useQuery({
    queryKey: webhookKeys.all,
    queryFn: async (): Promise<WebhookEndpoint[]> => {
      if (!userId) return [];

      const { data, error } = await supabase
        .from("webhook_endpoints")
        .select("*")
        .eq("user_id", userId)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return data as WebhookEndpoint[];
    },
    enabled: !!userId,
    staleTime: 1000 * 60, // 1 minute
  });
}

// ── useCreateWebhook ───────────────────────────────────────────
// Creates a new webhook endpoint with an auto-generated secret.

interface CreateWebhookInput {
  url: string;
  events?: string[];
}

export function useCreateWebhook() {
  const { profile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      url,
      events = ["scan.completed"],
    }: CreateWebhookInput): Promise<WebhookEndpoint> => {
      const userId = profile?.id;
      if (!userId) throw new Error("Not authenticated");

      const secret = crypto.randomUUID().replace(/-/g, "") + crypto.randomUUID().replace(/-/g, "");

      const insert: WebhookEndpointInsert = {
        user_id: userId,
        url,
        secret,
        events,
        is_active: true,
      };

      const { data, error } = await supabase
        .from("webhook_endpoints")
        .insert(insert)
        .select("*")
        .single();

      if (error) throw new Error(error.message);
      return data as WebhookEndpoint;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: webhookKeys.all });
    },
  });
}

// ── useDeleteWebhook ───────────────────────────────────────────
// Deletes a webhook endpoint by ID.

export function useDeleteWebhook() {
  const { profile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (id: string): Promise<void> => {
      const userId = profile?.id;
      if (!userId) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("webhook_endpoints")
        .delete()
        .eq("id", id)
        .eq("user_id", userId);

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: webhookKeys.all });
    },
  });
}

// ── useToggleWebhook ───────────────────────────────────────────
// Toggles is_active for a webhook endpoint.

export function useToggleWebhook() {
  const { profile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      id,
      is_active,
    }: {
      id: string;
      is_active: boolean;
    }): Promise<void> => {
      const userId = profile?.id;
      if (!userId) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("webhook_endpoints")
        .update({ is_active })
        .eq("id", id)
        .eq("user_id", userId);

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: webhookKeys.all });
    },
  });
}

import { useState } from "react";
import {
  Copy,
  Eye,
  EyeOff,
  Loader2,
  Plus,
  Trash2,
  Webhook,
} from "lucide-react";
import { toast } from "sonner";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Checkbox } from "@/components/ui/checkbox";
import { PremiumLock } from "@/components/shared/PremiumLock";
import { useAuth } from "@/contexts/AuthContext";
import { isProPlus } from "@/types/index";
import {
  useWebhooks,
  useCreateWebhook,
  useDeleteWebhook,
  useToggleWebhook,
} from "@/hooks/use-webhooks";
import type { WebhookEndpoint } from "@/types/index";

// ── Available event types ──────────────────────────────────────

const AVAILABLE_EVENTS: { value: string; label: string }[] = [
  { value: "scan.completed", label: "Scan Completed" },
];

// ── Secret display ─────────────────────────────────────────────

interface SecretCellProps {
  secret: string;
}

function SecretCell({ secret }: SecretCellProps) {
  const [revealed, setRevealed] = useState(false);

  const display = revealed ? secret : `${secret.slice(0, 8)}${"•".repeat(24)}`;

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(secret);
      toast.success("Secret copied to clipboard");
    } catch {
      toast.error("Failed to copy secret");
    }
  };

  return (
    <div className="flex items-center gap-1.5">
      <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-xs text-muted-foreground">
        {display}
      </code>
      <button
        type="button"
        onClick={() => setRevealed((v) => !v)}
        className="rounded p-1 text-muted-foreground hover:text-foreground"
        aria-label={revealed ? "Hide secret" : "Reveal secret"}
      >
        {revealed ? (
          <EyeOff className="h-3.5 w-3.5" />
        ) : (
          <Eye className="h-3.5 w-3.5" />
        )}
      </button>
      <button
        type="button"
        onClick={() => void handleCopy()}
        className="rounded p-1 text-muted-foreground hover:text-foreground"
        aria-label="Copy secret"
      >
        <Copy className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}

// ── Add webhook form ───────────────────────────────────────────

interface AddWebhookFormProps {
  onCancel: () => void;
}

function AddWebhookForm({ onCancel }: AddWebhookFormProps) {
  const [url, setUrl] = useState("");
  const [selectedEvents, setSelectedEvents] = useState<string[]>(["scan.completed"]);
  const [urlError, setUrlError] = useState<string | null>(null);
  const createWebhook = useCreateWebhook();

  const validateUrl = (value: string): boolean => {
    try {
      const parsed = new URL(value);
      if (parsed.protocol !== "https:") {
        setUrlError("URL must use HTTPS");
        return false;
      }
      setUrlError(null);
      return true;
    } catch {
      setUrlError("Enter a valid URL (e.g. https://example.com/webhook)");
      return false;
    }
  };

  const handleUrlChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setUrl(e.target.value);
    if (urlError) validateUrl(e.target.value);
  };

  const toggleEvent = (event: string, checked: boolean) => {
    setSelectedEvents((prev) =>
      checked ? [...prev, event] : prev.filter((e) => e !== event),
    );
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!validateUrl(url)) return;
    if (selectedEvents.length === 0) {
      toast.error("Select at least one event");
      return;
    }

    try {
      await createWebhook.mutateAsync({ url: url.trim(), events: selectedEvents });
      toast.success("Webhook endpoint created");
      onCancel();
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Failed to create webhook",
      );
    }
  };

  return (
    <form
      onSubmit={(e) => void handleSubmit(e)}
      className="rounded-lg border border-dashed border-border bg-muted/30 p-4 space-y-4"
    >
      <div className="space-y-1.5">
        <Label htmlFor="webhook-url">Endpoint URL</Label>
        <Input
          id="webhook-url"
          type="url"
          placeholder="https://example.com/webhook"
          value={url}
          onChange={handleUrlChange}
          disabled={createWebhook.isPending}
          autoFocus
          aria-describedby={urlError ? "webhook-url-error" : undefined}
        />
        {urlError && (
          <p id="webhook-url-error" className="text-xs text-destructive">
            {urlError}
          </p>
        )}
      </div>

      <div className="space-y-2">
        <Label>Events</Label>
        <div className="space-y-2">
          {AVAILABLE_EVENTS.map(({ value, label }) => (
            <div key={value} className="flex items-center gap-2">
              <Checkbox
                id={`event-${value}`}
                checked={selectedEvents.includes(value)}
                onCheckedChange={(checked) =>
                  toggleEvent(value, checked === true)
                }
                disabled={createWebhook.isPending}
              />
              <Label
                htmlFor={`event-${value}`}
                className="font-normal cursor-pointer"
              >
                {label}
              </Label>
            </div>
          ))}
        </div>
      </div>

      <div className="flex items-center gap-2">
        <Button
          type="submit"
          size="sm"
          disabled={!url.trim() || selectedEvents.length === 0 || createWebhook.isPending}
        >
          {createWebhook.isPending ? (
            <>
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              Creating…
            </>
          ) : (
            "Create Webhook"
          )}
        </Button>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={onCancel}
          disabled={createWebhook.isPending}
        >
          Cancel
        </Button>
      </div>
    </form>
  );
}

// ── Webhook row ────────────────────────────────────────────────

interface WebhookRowProps {
  endpoint: WebhookEndpoint;
}

function WebhookRow({ endpoint }: WebhookRowProps) {
  const deleteWebhook = useDeleteWebhook();
  const toggleWebhook = useToggleWebhook();

  const handleToggle = async (checked: boolean) => {
    try {
      await toggleWebhook.mutateAsync({ id: endpoint.id, is_active: checked });
    } catch {
      toast.error("Failed to update webhook status");
    }
  };

  const handleDelete = async () => {
    try {
      await deleteWebhook.mutateAsync(endpoint.id);
      toast.success("Webhook deleted");
    } catch {
      toast.error("Failed to delete webhook");
    }
  };

  const displayUrl =
    endpoint.url.length > 48
      ? `${endpoint.url.slice(0, 45)}…`
      : endpoint.url;

  return (
    <TableRow>
      <TableCell className="font-mono text-xs text-muted-foreground max-w-[200px] truncate" title={endpoint.url}>
        {displayUrl}
      </TableCell>
      <TableCell>
        <div className="flex flex-wrap gap-1">
          {endpoint.events.map((ev) => (
            <Badge
              key={ev}
              variant="secondary"
              className="text-xs font-mono"
            >
              {ev}
            </Badge>
          ))}
        </div>
      </TableCell>
      <TableCell>
        <SecretCell secret={endpoint.secret} />
      </TableCell>
      <TableCell>
        <Switch
          checked={endpoint.is_active}
          onCheckedChange={(checked) => void handleToggle(checked)}
          disabled={toggleWebhook.isPending}
          aria-label={`Toggle webhook ${endpoint.url}`}
        />
      </TableCell>
      <TableCell>
        <Button
          variant="ghost"
          size="icon"
          onClick={() => void handleDelete()}
          disabled={deleteWebhook.isPending}
          aria-label="Delete webhook"
          className="h-8 w-8 text-muted-foreground hover:text-destructive"
        >
          {deleteWebhook.isPending ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <Trash2 className="h-4 w-4" />
          )}
        </Button>
      </TableCell>
    </TableRow>
  );
}

// ── Skeleton ───────────────────────────────────────────────────

function WebhookSkeleton() {
  return (
    <div className="space-y-2">
      {Array.from({ length: 2 }).map((_, i) => (
        <div key={i} className="flex items-center gap-4 py-3 border-b border-border/50">
          <Skeleton className="h-4 w-48" />
          <Skeleton className="h-5 w-28 rounded-full" />
          <Skeleton className="h-4 w-40" />
          <Skeleton className="h-5 w-9 rounded-full" />
          <Skeleton className="h-8 w-8 rounded-md" />
        </div>
      ))}
    </div>
  );
}

// ── Main component ─────────────────────────────────────────────

export function WebhookManager() {
  const { profile } = useAuth();
  const [showForm, setShowForm] = useState(false);
  const { data: webhooks = [], isLoading } = useWebhooks();

  const isPro = isProPlus(profile?.plan ?? "free");

  const content = (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-base font-semibold text-foreground">Webhooks</h2>
          <p className="text-sm text-muted-foreground">
            Get notified when events happen in your account
          </p>
        </div>
        {!showForm && (
          <Button
            size="sm"
            onClick={() => setShowForm(true)}
            disabled={!isPro}
            className="gap-1.5"
          >
            <Plus className="h-4 w-4" />
            Add Webhook
          </Button>
        )}
      </div>

      {/* Inline add form */}
      {showForm && <AddWebhookForm onCancel={() => setShowForm(false)} />}

      {/* Table / states */}
      {isLoading ? (
        <WebhookSkeleton />
      ) : webhooks.length === 0 && !showForm ? (
        <div className="flex flex-col items-center justify-center gap-3 rounded-lg border border-dashed border-border py-10 text-center">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-muted">
            <Webhook className="h-5 w-5 text-muted-foreground" />
          </div>
          <div>
            <p className="text-sm font-medium text-foreground">
              No webhooks configured
            </p>
            <p className="mt-0.5 text-xs text-muted-foreground">
              Add one to receive scan results in real time.
            </p>
          </div>
          <Button
            size="sm"
            variant="outline"
            onClick={() => setShowForm(true)}
            disabled={!isPro}
          >
            <Plus className="mr-1.5 h-4 w-4" />
            Add Webhook
          </Button>
        </div>
      ) : webhooks.length > 0 ? (
        <div className="rounded-md border border-border/50 overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>URL</TableHead>
                <TableHead>Events</TableHead>
                <TableHead>Secret</TableHead>
                <TableHead>Active</TableHead>
                <TableHead className="w-10" />
              </TableRow>
            </TableHeader>
            <TableBody>
              {webhooks.map((endpoint) => (
                <WebhookRow key={endpoint.id} endpoint={endpoint} />
              ))}
            </TableBody>
          </Table>
        </div>
      ) : null}
    </div>
  );

  if (!isPro) {
    return (
      <PremiumLock message="Webhooks are available on Pro and Agency plans">
        {content}
      </PremiumLock>
    );
  }

  return content;
}

